const evento = $input.first().json;
const execucao = evento.execution ?? {};
const workflow = evento.workflow ?? {};
const trigger = evento.trigger ?? {};

const mensagem = execucao.error?.message
  ?? trigger.error?.message
  ?? evento.error?.message
  ?? 'Erro sem mensagem detalhada';

const ultimoNo = execucao.lastNodeExecuted
  ?? trigger.lastNodeExecuted
  ?? 'não informado';

const nomeWorkflow = workflow.name ?? 'workflow não informado';
const urlExecucao = execucao.url ?? '';

const escapar = (valor) => String(valor ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#039;');

return [{
  json: {
    assunto: `ERRO n8n: ${nomeWorkflow}`,
    html: `
      <h2>Falha em uma automação</h2>
      <p><strong>Workflow:</strong> ${escapar(nomeWorkflow)}</p>
      <p><strong>Último nó:</strong> ${escapar(ultimoNo)}</p>
      <p><strong>Erro:</strong> ${escapar(mensagem)}</p>
      ${urlExecucao ? `<p><a href="${escapar(urlExecucao)}">Abrir execução no n8n</a></p>` : ''}
    `,
  },
}];
